<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useAuth } from '../stores/auth'
import { useRoute } from 'vue-router'
import { customerServiceMessageApi } from '../api/customer-rag'

const auth=useAuth(); const route=useRoute(); const focusSessionId=ref(String(route.query.customer_service_session_id||'')); const sessions=ref<any[]>([]); const selected=ref<any>(null); const messages=ref<any[]>([]); const draft=ref(''); const loading=ref(false); const error=ref(''); const connectionState=ref<'connected'|'recovering'|'paused'>('connected'); const focusWindow=ref(false); let timer:number|undefined
const canAssign=computed(()=>auth.me.value?.permissions?.includes('customer_service:assign')||auth.me.value?.is_super_admin)
async function load(){try{const next=(await customerServiceMessageApi.sessions('waiting_human')).data.data||[];sessions.value=next;connectionState.value='connected';if(focusSessionId.value&&selected.value?.id!==focusSessionId.value){const focused=next.find((row:any)=>row.id===focusSessionId.value) || await customerServiceMessageApi.session(focusSessionId.value).then((response:any)=>response.data.data).catch(()=>null);if(focused&&['waiting_human','paused','human_active'].includes(focused.status)){await selectSession(focused)}else if(focusSessionId.value){focusSessionId.value='';window.history.replaceState({},'',window.location.pathname+'?section=customer-service')}}else if(selected.value&&selected.value.status!=='human_active'&&selected.value.status!=='paused'){const fresh=next.find((row:any)=>row.id===selected.value.id);if(fresh)selected.value=fresh;else{selected.value=null;messages.value=[];focusWindow.value=false}}}catch(e:any){connectionState.value='recovering';error.value=e.message||'待接入会话加载失败'}}
async function selectSession(row:any){selected.value=row; await refreshMessages()}
async function refreshMessages(){if(!selected.value)return;try{messages.value=(await customerServiceMessageApi.messages(selected.value.id)).data.data||[];connectionState.value='connected'}catch(e:any){connectionState.value='recovering';error.value=e.message||'消息加载失败'}}
async function claim(){if(!selected.value)return;loading.value=true;try{const claimed=(await customerServiceMessageApi.claim(selected.value.id)).data.data;selected.value=claimed;focusWindow.value=true;await refreshMessages()}catch(e:any){error.value=e.message||'接入失败'}finally{loading.value=false}}
function closeFocus(){focusWindow.value=false}
async function send(){if(!selected.value||!draft.value.trim())return;try{await customerServiceMessageApi.send(selected.value.id,draft.value.trim());draft.value='';await refreshMessages()}catch(e:any){error.value=e.message||'发送失败'}}
async function pause(){if(!selected.value)return;try{selected.value=(await customerServiceMessageApi.pause(selected.value.id,'客服暂时离开')).data.data;await refreshMessages()}catch(e:any){error.value=e.message||'暂停失败'}}
async function release(){if(!selected.value)return;try{selected.value=(await customerServiceMessageApi.release(selected.value.id,'转回待接入队列')).data.data;await load()}catch(e:any){error.value=e.message||'转交失败'}}
async function resolve(){if(!selected.value)return;const note=window.prompt('请输入本次服务处理说明');if(!note?.trim())return;try{selected.value=(await customerServiceMessageApi.resolve(selected.value.id,note)).data.data;await load()}catch(e:any){error.value=e.message||'结束服务失败'}}
async function heartbeat(){if(!selected.value||selected.value.status!=='human_active')return;try{selected.value=(await customerServiceMessageApi.heartbeat(selected.value.id)).data.data;connectionState.value='connected';error.value=''}catch(e:any){const status=Number(e?.response?.status||0);if(status===409){selected.value={...selected.value,status:'paused'};connectionState.value='paused';error.value='会话已不再处于有效接入状态，请从待接入队列重新选择并接入。';await load();return}connectionState.value='recovering';error.value='客服连接暂时不可用，正在恢复…';await refreshMessages()}}
watch(()=>route.query.customer_service_session_id,(id)=>{focusSessionId.value=typeof id==='string'?id:'';load()},{immediate:true})
onMounted(()=>{load();timer=window.setInterval(()=>{load();if(selected.value&&selected.value.status==='human_active'){heartbeat();refreshMessages()}else if(selected.value&&selected.value.status==='paused')refreshMessages()},2500)})
onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)})
</script>
<template><section class="workspace-page customer-service-desk"><div class="section-heading"><div><span class="eyebrow">LIVE CUSTOMER SERVICE</span><h2 data-testid="customer-service-desk-title">实时客服工作台</h2><p>待接入会话、人工消息和会话退出边界。</p></div><div class="row-actions"><button class="button secondary" @click="load">刷新</button><button v-if="selected?.status==='human_active'" class="button" @click="focusWindow=true">打开对话窗口</button></div></div><p v-if="connectionState!=='connected'" class="muted">{{connectionState==='paused'?'会话已暂停，请点击“接入”恢复。':'连接恢复中…'}}</p><p v-if="error" class="error">{{error}}</p><div class="service-desk-layout"><aside class="panel-card service-queue"><h3 data-testid="customer-service-queue-title">待接入队列</h3><p v-if="!sessions.length" class="muted">暂无待接入会话</p><button v-for="row in sessions" :key="row.id" data-testid="customer-service-queue-item" class="service-queue-item" :class="{selected:selected?.id===row.id}" @click="selectSession(row)"><b>{{row.id.slice(0,8)}}…</b><span>{{row.handoff_reason}} · {{row.status}}</span></button></aside><main class="panel-card service-chat"><div v-if="selected" data-testid="customer-service-selected-session" class="service-chat-header"><div><b>客户会话 {{selected.id.slice(0,8)}}…</b><small>{{selected.status}} · {{selected.customer_id}}</small></div><div class="row-actions"><button v-if="selected.status==='waiting_human'||selected.status==='paused'" class="button" @click="claim" :disabled="loading">接入</button><button v-if="selected.status==='human_active'" class="ghost-button" @click="pause">暂停</button><button v-if="selected.status==='human_active'" class="ghost-button" @click="release">转交</button><button v-if="selected.status==='human_active'||selected.status==='paused'" class="ghost-button" @click="resolve">结束</button></div></div><div v-else class="service-chat-empty">请选择左侧待接入会话。</div><div v-if="selected" data-testid="customer-service-messages" class="service-chat-messages"><article v-for="item in messages" :key="item.id" :class="['desk-message',item.sender_type]"><small>{{item.sender_type}}</small><p>{{item.content}}</p></article></div><div v-if="selected&&selected.status==='human_active'" data-testid="customer-service-compose" class="service-chat-compose"><textarea v-model="draft" data-testid="customer-service-reply-input" placeholder="输入人工客服回复" @keydown.enter.exact.prevent="send"/><button class="button" :disabled="!draft.trim()" @click="send">发送</button></div></main></div><div v-if="focusWindow&&selected?.status==='human_active'" class="customer-chat-modal-backdrop" @click.self="closeFocus"><section class="customer-chat-modal" data-testid="customer-chat-modal"><header><div><span class="eyebrow">ACTIVE CONVERSATION</span><h3>客户实时对话</h3><small>{{selected.id.slice(0,8)}}… · {{selected.customer_id}}</small></div><button class="ghost-button" @click="closeFocus">×</button></header><div class="service-chat-messages"><article v-for="item in messages" :key="item.id" :class="['desk-message',item.sender_type]"><small>{{item.sender_type}}</small><p>{{item.content}}</p></article></div><div data-testid="customer-service-compose-modal" class="service-chat-compose"><textarea v-model="draft" data-testid="customer-service-reply-input-modal" placeholder="输入人工客服回复" @keydown.enter.exact.prevent="send"/><button class="button" :disabled="!draft.trim()" @click="send">发送</button></div></section></div></section></template>
